package dev.clean.lift.widgets

data class WidgetGuide(val equipment: String, val protocol: String, val sourceTitle: String, val sourceUrl: String)
object WidgetGuides {
    fun forProtocol(kind: WidgetProtocol): WidgetGuide = when (kind) {
        WidgetProtocol.PUSH_UP -> WidgetGuide("Flat level floor, shoes, observer and timer.",
            "Navy Guide 5A form: straight body, toes and palms supporting weight, hands under/slightly outside shoulders. Lower until elbows bend at least 90°, then return to straight arms. Count correct repetitions in two minutes. Rest only in the up position; end when form/rest rules fail. The app gives 15-second tone cues; the observer announces times. Practice only: Navy official testing prohibits cellphone stopwatches.", "Navy • Guide 5A, December 2025, pp. 9–10", "https://www.mynavyhr.navy.mil/Portals/55/Support/Culture%20Resilience/Physical/Guide-5A%20Physical%20Readiness%20Test.pdf")
        WidgetProtocol.PULL_UP -> WidgetGuide("Secure high pull-up bar and observer. Record overhand/underhand grip in notes.",
            "USMC dead-hang form: begin motionless with arms fully extended and feet clear. Raise chin above the bar, then fully extend elbows. No kicking, kipping, assisted momentum or resting chin on the bar. Both palms face forward or rearward. Count correct repetitions until dropping off the bar; this is an untimed event.", "Marine Corps • MCO 6100.13A, enclosure 1, p. 2-3", "https://www.marines.mil/Portals/1/Publications/MCO%206100.13A%20W%20ADMIN%20CH-5%20%28SECURED%29.pdf")
        WidgetProtocol.PLANK -> WidgetGuide("Flat mat/floor, observer and timer.",
            "AFMAN 2026 forearm form: elbows under shoulders at 90°, hands in fists or flat (not clasped), feet hip width. Keep head-to-heels straight; only forearms, hands and toes touch the floor. End on loss of position/contact or the third form correction. This personal benchmark uses the same 3:40 cap for everyone to keep comparisons consistent; an Air Force assessment uses the selected age/sex maximum instead. Tone cues every 15 seconds.", "Air Force • AFMAN 36-2905, Attachment 2, A2.7", AirForceScoring.MANUAL_URL)
        WidgetProtocol.COOPER -> WidgetGuide("Measured level track/course, observer, distance markers and timer.",
            "Warm up, then cover as much measured distance as possible in exactly 12 minutes. Running or walking is allowed. Record the total metres reached at the end cue, including the final partial lap. Keep course and conditions consistent. A valid distance can be saved even when outside the existing estimate's 505–6000 m range. The estimate is a field prediction, not a measured laboratory VO₂ result.", "Cooper Institute • 12-minute test background", "https://www.cooperinstitute.org/blog/50-years-of-the-cooper-12-minute-run")
        WidgetProtocol.ROCKPORT -> WidgetGuide("Measured level track/course of exactly 1 mile (1609.344 m), stopwatch, scale and immediate finishing pulse.",
            "Warm up, then walk the mile as quickly as possible without jogging. End the clock at the finish and measure pulse immediately in bpm. Record course, conditions and pulse method. Estimate uses the existing Kline equation with weight, age 20–69, M/F equation category, time and pulse. Raw walk time can be saved without an estimate. Track protocol; treadmill results are not equivalent.", "Kline et al. • original Rockport study, 1987", "https://pubmed.ncbi.nlm.nih.gov/3600239/")
        WidgetProtocol.PACER -> WidgetGuide("Two lines exactly 20 m apart, suitable lanes, official 20 m FitnessGram recording and observer.",
            "Progressive recorded cues control arrivals. Touch the line by the cue; second miss ends the 2010 protocol. An observer records the final score. Use the matching official audio and score sheet. No 15 m conversion or youth fitness grading is provided. Audio interruptions exclude the attempt from comparable trends.", "Cooper Institute • PACER instructions, 2010", "https://resources.finalsite.net/images/v1710865382/hebisdedu/mswuhakyitgev6btcucc/1_PACER_and_Mile_Run.pdf")
        WidgetProtocol.HAMR -> WidgetGuide("Two lines exactly 20 m apart, suitable lanes, approved Air Force HAMR recording and observer.",
            "Touch the far line before its cue; wait for departure if early. Three consecutive warnings end the test, and a successful shuttle resets warnings. Always reach each far line; cutting short, resting or skipping terminates the test. Score the last successful shuttle number. The recording provides cues; the observer judges each shuttle.", "Air Force • AFMAN 36-2905, A2.9", AirForceScoring.MANUAL_URL)
        WidgetProtocol.AIR_FORCE -> WidgetGuide("Tape, height measure, flat floor/mat, observer, certified 2-mile course or 20 m HAMR course and approved recording.",
            "2026 standard PFRA practice: body composition first, then strength, core and cardio. Minimum five-minute rests between physical components; finish all physical components within three hours. Select M/F table and age explicitly. No medical exemptions, secondary BFA, altitude correction (≥5250 ft) or command-specific waivers are scored. Every saved result retains its scoring version and inputs. Official scores require authorized administration and myFitness entry.", "Air Force • AFMAN 36-2905, 24 March 2026", AirForceScoring.MANUAL_URL)
    }
}
